From a031f6880fbbdeea86c4c1458ed9a6df4ac6846f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 18:24:03 +0100
Subject: [PATCH] sm: Ask web browsers to quit as a whole when logging out

Closing every window of a browser one by one made it treat all but the
last as closed by the user, so only that one came back after logging in
again. Send the browser SIGTERM instead, which it handles as a full quit.

BUG: 511236
---
 src/sm.cpp | 26 ++++++++++++++++++++++++--
 1 file changed, 24 insertions(+), 2 deletions(-)

diff --git a/src/sm.cpp b/src/sm.cpp
index 7a4591880a..f0254b7213 100644
--- a/src/sm.cpp
+++ b/src/sm.cpp
@@ -10,12 +10,15 @@

 #include "sm.h"

+#include <csignal>
 #include <cstdlib>
 #include <kconfig.h>
 #include <pwd.h>
 #include <unistd.h>

 #include "virtualdesktops.h"
+#include "wayland/clientconnection.h"
+#include "wayland/surface.h"
 #include "wayland_server.h"
 #include "workspace.h"
 #include "xdgshellwindow.h"
@@ -24,11 +27,12 @@
 #include "x11window.h"
 #endif

+#include <KService>
 #include <QSessionManager>
+#include <QSet>
 #if KWIN_BUILD_NOTIFICATIONS
 #include <KLocalizedString>
 #include <KNotification>
-#include <KService>
 #endif

 #include "sessionadaptor.h"
@@ -364,6 +368,12 @@ void SessionManager::finishSaveSession(const QString &name)
     storeSession(name, SMSavePhase2);
 }

+static bool isWebBrowser(const XdgToplevelWindow *window)
+{
+    const auto service = KService::serviceByDesktopName(window->desktopFileName());
+    return service && service->categories().contains(QLatin1StringView("WebBrowser"));
+}
+
 bool SessionManager::closeWaylandWindows()
 {
     Q_ASSERT(calledFromDBus());
@@ -382,6 +392,7 @@ bool SessionManager::closeWaylandWindows()
     const auto windows = workspace()->windows();
     m_pendingWindows.clear();
     m_pendingWindows.reserve(windows.size());
+    QSet<ClientConnection *> terminatedClients;
     for (const auto window : windows) {
         if (auto toplevelWindow = qobject_cast<XdgToplevelWindow *>(window)) {
             connect(toplevelWindow, &XdgToplevelWindow::closed, m_closingWindowsGuard.get(), [this, toplevelWindow, dbusMessage] {
@@ -402,7 +413,18 @@ bool SessionManager::closeWaylandWindows()
                 }
             });
             m_pendingWindows.push_back(toplevelWindow);
-            toplevelWindow->closeWindow();
+            // Browsers treat each closed window as closed by the user and drop it from their
+            // session, so ask them to quit as a whole instead, like the end of an X11 session.
+            ClientConnection *client = toplevelWindow->surface()->client();
+            const pid_t pid = client->processId();
+            if (pid > 0 && pid != getpid() && isWebBrowser(toplevelWindow)) {
+                if (!terminatedClients.contains(client)) {
+                    terminatedClients.insert(client);
+                    ::kill(pid, SIGTERM);
+                }
+            } else {
+                toplevelWindow->closeWindow();
+            }
         }
     }

